* {
  box-sizing: border-box;
}

body {
  margin: 0;
  font-family: system-ui, -apple-system, 'Segoe UI', sans-serif;
  color: #111827;
  background: #f9fafb;
}

.json-page {
  display: grid;
  gap: 12px;
  max-width: 640px;
  margin: 0 auto;
  padding: 16px;
}

.field {
  display: grid;
  gap: 6px;
  font-weight: 600;
}

.sample,
.json-input {
  font: inherit;
  font-weight: 400;
}

.json-input {
  width: 100%;
  padding: 8px;
  font-family: ui-monospace, 'SFMono-Regular', Menlo, monospace;
  font-size: 13px;
}

.json-viewer,
.json-children {
  margin: 0;
  padding: 0;
  list-style: none;
  font-family: ui-monospace, 'SFMono-Regular', Menlo, monospace;
  font-size: 13px;
}

.json-children {
  padding-left: 20px;
}

.json-entry {
  padding: 2px 0;
  overflow-wrap: anywhere;
}

.json-toggle {
  width: 20px;
  padding: 0;
  border: 0;
  background: none;
  font: inherit;
  cursor: pointer;
}

.json-key {
  color: #7c3aed;
}

.json-key::after {
  content: ': ';
  color: #6b7280;
}

.json-value {
  color: #047857;
}

.json-summary {
  color: #6b7280;
}

.json-error {
  margin: 0;
  padding: 12px;
  border-radius: 8px;
  color: #991b1b;
  background: #fef2f2;
}

.json-raw {
  margin: 0;
  white-space: pre-wrap;
}
